struct vector3d
{
  float x;
  float y;
  float z;
};

struct sphere
{
  sphere(const vector3d& p, float r) : center(p), radius(r) {}
  vector3d center;
  float radius;
};

extern int visit_counter;

struct region
{
  char pad[284];
  int visit_marker;
  void visit() { visit_marker = visit_counter; }
  bool already_visited() const { return visit_marker == visit_counter; }
};

struct portal
{
  bool touches_sphere(const sphere&) const
    __asm__("touches_sphere__C6portalRC6sphere");
};

struct graph_edge
{
  graph_edge* next;
  graph_edge* prev;
  portal* data;
  struct region_node* dest;
  portal* get_data() const { return data; }
  region_node* get_dest() const { return dest; }
};

struct edge_iterator
{
  graph_edge* edge;
  edge_iterator(graph_edge* p) : edge(p) {}
  graph_edge& operator*() const { return *edge; }
  edge_iterator& operator++() { edge = edge->next; return *this; }
  bool operator!=(const edge_iterator& rhs) const { return edge != rhs.edge; }
};

struct region_node
{
  graph_edge* edges;
  region* data;
  region* get_data() const { return data; }
  edge_iterator begin() { return edge_iterator(edges->next); }
  edge_iterator end() { return edge_iterator(edges); }
};

template<class T>
struct vector
{
  T* begin_;
  T* end_;
  T* capacity_;
  void push_back(const T& value)
    __asm__("_M_insert_aux__t6vector2ZP6regionZt12my_allocator1ZP6regionPP6regionRCP6region");
};

struct trigger_manager
{
  char pad[4];
  vector<region*> new_regions;
  static trigger_manager* inst();
};

extern trigger_manager* trigger_manager_instance;
inline trigger_manager* trigger_manager::inst() { return trigger_manager_instance; }

class point_trigger
{
public:
  char pad[56];
  vector3d position;
  float radius;
  void _intersect(region_node* r)
    __asm__("_intersect__13point_triggerPQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4node");
};

__asm__(".equ visit_counter,0x00434948");
__asm__(".equ trigger_manager_instance,0x00431A88");
__asm__(".equ touches_sphere__C6portalRC6sphere,0x002E4ED8");
__asm__(".equ _M_insert_aux__t6vector2ZP6regionZt12my_allocator1ZP6regionPP6regionRCP6region,0x002B0638");

// add trigger to given region and recurse into any adjacent intersected regions
void point_trigger::_intersect( region_node* r )
{
  // add NEW region to temp list
  region* rg = r->get_data();
  rg->visit();
  trigger_manager::inst()->new_regions.push_back( rg );
  sphere trig_sphere(position,radius);
  // check for intersection with portals leading from this region
  edge_iterator ei = r->begin();
  edge_iterator ei_end = r->end();
  for ( ; ei!=ei_end; ++ei )
  {
    // don't bother with regions we've already visited
    region_node* dest = (*ei).get_dest();
    if ( !dest->get_data()->already_visited() )
    {
      portal* port = (*ei).get_data();
      if ( port->touches_sphere(trig_sphere) )
        _intersect( dest );
    }
  }
}
